import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int m = sc.nextInt();

        // Function for binary exponentiation
        class BinPow {
            long binPow(int base, int exp) {
                long res = 1;
                long b = base;
                while (exp > 0) {
                    if ((exp & 1) == 1) {
                        res = (res * b) % m;
                    }
                    b = (b * b) % m;
                    exp >>= 1;
                }
                return res;
            }
        }
        BinPow bp = new BinPow();

        if (n % 2 == 1) {
            System.out.println(bp.binPow(k, n));
        } else {
            long[] fact = new long[n + 1];
            long[] invFact = new long[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % m;
            }
            invFact[n] = bp.binPow((int) fact[n], m - 2);
            for (int i = n - 1; i >= 0; i--) {
                invFact[i] = (invFact[i + 1] * (i + 1)) % m;
            }

            List<Integer> positions = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (((n & (1 << i)) != 0)) {
                    positions.add(i);
                }
            }

            int[] segmentSizes = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                int j = i;
                while (j != 0) {
                    segmentSizes[i]++;
                    j = (j - 1) & j;
                }
            }

            boolean[] visitedMask = new boolean[1 << n];
            for (int mask = (1 << n) - 1; mask >= 0; mask--) {
                if (mask == 0) break;
                visitedMask[mask] = true;
            }

            long[][] dp = new long[n + 1][1 << n];
            dp[0][0] = 1;

            for (int mask = 0; mask < (1 << n); mask++) {
                for (int s = 0; s <= n; s++) {
                    if (dp[s][mask] == 0) continue;
                    int subMask = mask;
                    while (subMask != 0) {
                        subMask = (subMask - 1) & mask;
                        int remaining = mask ^ subMask;
                        int l = Math.min(k, segmentSizes[remaining] + 1);
                        for (int s2 = 1; s2 <= l; s2++) {
                            if (dp[s - 1][remaining] != 0) {
                                long val = (dp[s - 1][remaining] * invFact[subMask]) % m;
                                dp[s][mask] = (dp[s][mask] + val) % m;
                            }
                        }
                    }
                }
            }

            long total = 0;
            int fullMask = (1 << n) - 1;
            int maxI = Math.min(k, segmentSizes[n]);
            for (int i = 0; i <= maxI; i++) {
                if (dp[i][fullMask] != 0) {
                    long val = dp[i][fullMask];
                    val = (val * fact[k]) % m;
                    val = (val * invFact[k - i]) % m;
                    val = (val * invFact[i]) % m;
                    val = (val * fact[n]) % m;
                    total = (total + val) % m;
                }
            }
            long result = (bp.binPow(k, n) - total + m) % m;
            System.out.println(result);
        }
        sc.close();
    }
}

